$nullah_geojson$::jsonb->'features') AS feature
), merged AS (
  SELECT ST_Multi(ST_CollectionExtract(ST_Collect(geom), 2))::geometry(MultiLineString,4326) AS geom
  FROM source
)
UPDATE public.drainage_lines d
SET name = 'Nullah Lai (mapped OSM centreline)',
    source_note = 'OpenStreetMap-derived; student GIS mapping, not surveyed or field verified',
    geom = merged.geom
FROM merged
WHERE d.id = (SELECT MIN(id) FROM public.drainage_lines);

-- Post-import check: number of line parts and actual length.
SELECT id, name, ST_SRID(geom) AS srid, ST_GeometryType(geom) AS geom_type,
       ST_NumGeometries(geom) AS segments,
       ROUND((ST_Length(geom::geography)/1000)::numeric,2) AS length_km
FROM public.drainage_lines ORDER BY id;
COMMIT;
